CREATE FUNCTION public.create_lead(t uuid,contact_name text,contact_company text,contact_phone text,contact_email text,deal_value numeric) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c uuid; l uuid; BEGIN IF NOT public.is_member(t) THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.contacts(tenant_id,name,company,phone,email) VALUES(t,contact_name,contact_company,contact_phone,contact_email) RETURNING id INTO c; INSERT INTO public.leads(tenant_id,contact_id,owner_id,value) VALUES(t,c,auth.uid(),deal_value) RETURNING id INTO l; RETURN l; END $$;
REVOKE ALL ON FUNCTION public.create_lead(uuid,text,text,text,text,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_lead(uuid,text,text,text,text,numeric) TO authenticated;
CREATE FUNCTION public.validate_invite() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.accepted_at IS NOT NULL OR NEW.expires_at>now()+interval '7 days' OR NEW.expires_at<=now() THEN RAISE EXCEPTION 'Invalid invitation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER invite_validation BEFORE INSERT ON public.tenant_invitations FOR EACH ROW EXECUTE FUNCTION public.validate_invite();
CREATE FUNCTION public.touch_lead() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER lead_touch BEFORE UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.touch_lead();